// Wave GEN lane K (C-AGI): agility-scaled joint limits, the balance disk, the Skeleton stage's disks and
// T-pose, and the animation audit's fixes. SPEC G40-G59. The audit numbers themselves are generated by
// tools/audit-animations.ts (artifacts/wave-gen/anim-audit-{before,after}.json, docs/wave-gen/KINEMATICS.md).
import { defaultHumanoid, type JointName } from "../src/game/Skeleton.ts";
import {
  AGILITY_NARROW, AGILITY_REFERENCE, AGILITY_WIDEN, agilityLimits, agilityScale, ANATOMICAL_CAP, HARD_STOPS, totalTravel,
} from "../src/game/anim/AgilityLimits.ts";
import { skeletonDisks, tPose, tPoseBones, tPoseDisks } from "../src/game/anim/SkeletonDisks.ts";
import { balanceDisk, capsuleCentreOfMass, convexHull, lateralXcomMargin, polygonMargin } from "../src/game/anim/BalanceDisk.ts";
import { Animator } from "../src/game/anim/Animator.ts";
import { JOINT_ORDER, legGeometryFromBones, limitTableFrom } from "../src/game/anim/Rig.ts";
import { anatomyFor } from "../src/graphics/body/Anatomy.ts";
import { gripExcluded } from "../src/combat/SelfGuard.ts";
import { OFF_ARM_RATE } from "../src/combat/OffHand.ts";
import { ARM_RELEASE_RATE } from "../src/graphics/body/SkinnedHumanoid.ts";
import { weaponFromSeed } from "../src/game/weapons/Generate.ts";
import { ARCHETYPE_IDS } from "../src/game/weapons/Archetypes.ts";
import { ALL_SKILLS } from "../src/game/Skills.ts";
import { agilityTable, allClips, type AuditReport, BODIES, docTables, runClip, THRESHOLDS } from "../tools/audit-animations.ts";
import type { BodySpec, Vec3 } from "../src/graphics/body/contracts.ts";
import type { Hitbox } from "../src/combat/contracts.ts";

function assert(ok: unknown, m = "assertion failed"): asserts ok { if (!ok) throw new Error(m); }
const ref = () => defaultHumanoid().limits();
const RACES = ["human", "elf", "dwarf", "ork"] as const;
const specOf = (race: string): BodySpec => ({ race, subrace: null, className: "Warrior", height: race === "dwarf" ? 1.39 : race === "ork" ? 1.95 : 1.72, weight: race === "ork" ? 120 : 70, seed: 7 });

// ─── C-AGI: agility-scaled limits ──────────────────────────────────────────────────────────────

Deno.test("SPEC G40: agilityLimits is the identity (same numbers) at the reference 500 and for an absent agility", () => {
  for (const a of [AGILITY_REFERENCE, null, undefined, Number.NaN]) {
    const out = agilityLimits(ref(), a as number);
    for (const [n, l] of ref()) {
      const o = out.get(n)!;
      assert(Object.is(o.min, l.min) && Object.is(o.max, l.max) && Object.is(o.rest, l.rest), `${String(a)} ${n}: ${JSON.stringify(o)} vs ${JSON.stringify(l)}`);
    }
  }
  assert(agilityScale(500) === 1 && agilityScale(1000) === 1 + AGILITY_WIDEN && agilityScale(0) === 1 - AGILITY_NARROW, "scale endpoints");
});

Deno.test("SPEC G41: windows are nested and monotone in agility (0 ⊂ 250 ⊂ 500 ⊂ 750 ⊂ 1000), total travel rising", () => {
  const steps = [0, 250, 500, 750, 1000].map((a) => agilityLimits(ref(), a));
  for (let i = 1; i < steps.length; i++) {
    for (const [n, l] of steps[i]) {
      const p = steps[i - 1].get(n)!;
      assert(l.min <= p.min + 1e-12 && l.max >= p.max - 1e-12, `${n}: window at step ${i} not nested`);
    }
    assert(totalTravel(steps[i]) > totalTravel(steps[i - 1]), `travel not rising at step ${i}`);
  }
});

Deno.test("SPEC G42: the widening is bounded (≤ AGILITY_WIDEN per side, inside ANATOMICAL_CAP); the narrowing ≤ AGILITY_NARROW", () => {
  const wide = agilityLimits(ref(), 1000), narrow = agilityLimits(ref(), 0), big = agilityLimits(ref(), 1e9);
  for (const [n, l] of ref()) {
    const w = wide.get(n)!, s = narrow.get(n)!, cap = ANATOMICAL_CAP[n];
    assert(w.min >= cap.min - 1e-12 && w.max <= cap.max + 1e-12, `${n}: ${JSON.stringify(w)} outside the cap`);
    assert(l.rest - w.min <= (l.rest - l.min) * (1 + AGILITY_WIDEN) + 1e-12 && w.max - l.rest <= (l.max - l.rest) * (1 + AGILITY_WIDEN) + 1e-12, `${n}: widened past 15 %`);
    assert(l.rest - s.min >= (l.rest - l.min) * (1 - AGILITY_NARROW) - 1e-12 && s.max - l.rest >= (l.max - l.rest) * (1 - AGILITY_NARROW) - 1e-12, `${n}: narrowed past 10 %`);
    assert(JSON.stringify(big.get(n)) === JSON.stringify(w), `${n}: agility is clamped to 1000`);
  }
});

Deno.test("SPEC G43: hard stops never move (elbow / knee hyperextension), rest always stays inside", () => {
  for (const a of [0, 300, 500, 800, 1000]) {
    const out = agilityLimits(ref(), a);
    for (const [n, l] of out) {
      const stop = HARD_STOPS[n];
      if (stop?.max) assert(l.max === ref().get(n)!.max, `${n} @${a}: max moved to ${l.max}`);
      assert(l.min <= l.rest && l.rest <= l.max, `${n} @${a}: rest outside`);
    }
  }
});

Deno.test("SPEC G44: Skeleton.setAgility / defaultHumanoid(agility) carry the table; defaultHumanoid(500) == defaultHumanoid()", () => {
  const a = defaultHumanoid(), b = defaultHumanoid(500), c = defaultHumanoid(1000), d = defaultHumanoid();
  assert(JSON.stringify([...a.limits()]) === JSON.stringify([...b.limits()]), "500 is the reference table");
  assert(JSON.stringify([...c.limits()]) === JSON.stringify([...agilityLimits(ref(), 1000)]), "1000 is agilityLimits(1000)");
  d.setAgility(1000); d.setAgility(500);
  assert(JSON.stringify([...d.limits()]) === JSON.stringify([...a.limits()]), "setAgility round-trips to the reference");
  assert(c.agility === 1000 && a.agility === 500, "agility getter");
});

/** Drive an Animator (human plan bones) with a constant attack pose asking for a shoulder flexion of -2.75. */
function reachShoulder(agility: number): number {
  const plan = anatomyFor(specOf("human"));
  const sk = defaultHumanoid(agility);
  const ankleY = plan.bones.find((b) => b.id === "ankleL")!.head[1];
  const an = new Animator(legGeometryFromBones(plan.bones, ankleY, 1), limitTableFrom(sk.limits()));
  const pose = Float64Array.from(limitTableFrom(sk.limits()).rest);
  pose[JOINT_ORDER.indexOf("shoulderR")] = -2.75;
  let out = 0;
  for (let k = 0; k < 90; k++) {
    const o = an.update(1 / 60, {
      x: 0, z: 0, yaw: 0, rootY: 0, speed: 0, moveDirLocal: 0, turnRate: 0, grounded: true, hit: false, attack: true, attackPose: pose,
      block: false, ko: false, engaged: true, skill: null, skillProgress: 0, groundHeight: () => 0,
    });
    sk.drive(o.angles, o.hipRoll, o.ankleRoll, o.toeOut);
    sk.update(1 / 60);
    out = sk.joint("shoulderR").angle;
  }
  return out;
}

Deno.test("SPEC G45: an agile fighter's Animator + Skeleton REACH further (shoulder flexion asked -2.75 rad)", () => {
  const r0 = reachShoulder(0), r5 = reachShoulder(500), r10 = reachShoulder(1000);
  console.log(`shoulderR reached: agility 0 ${r0.toFixed(3)}, 500 ${r5.toFixed(3)}, 1000 ${r10.toFixed(3)} rad`);
  assert(Math.abs(r5 - -2.4) < 1e-6, `reference stops at the reference limit (${r5})`);
  assert(r10 < -2.7 && r10 >= ANATOMICAL_CAP.shoulderR.min, `agile reaches past -2.7 (${r10})`);
  assert(r0 > -2.17 && r0 < r5 + 0.3, `stiff stops near -2.16 (${r0})`);
});

Deno.test("SPEC G46: at the reference agility the Animator's output is bit-identical (absent vs 500)", () => {
  const plan = anatomyFor(specOf("dwarf"));
  const ankleY = plan.bones.find((b) => b.id === "ankleL")!.head[1];
  const run = (sk: ReturnType<typeof defaultHumanoid>) => {
    const an = new Animator(legGeometryFromBones(plan.bones, ankleY, 1), limitTableFrom(sk.limits()));
    const acc: number[] = [];
    for (let k = 0; k < 60; k++) {
      const o = an.update(1 / 60, {
        x: 0, z: k * 0.035, yaw: 0, rootY: 0, speed: 2.1, moveDirLocal: 0, turnRate: 0, grounded: true, hit: false, attack: false,
        block: false, ko: false, engaged: false, skill: null, skillProgress: 0, groundHeight: () => 0,
      });
      acc.push(...o.angles, o.rootOffsetY);
    }
    return acc;
  };
  const a = run(defaultHumanoid()), b = run(defaultHumanoid(500));
  assert(a.length === b.length && a.every((v, i) => Object.is(v, b[i])), "reference agility changed the motion");
});

// ─── Skeleton stage: disks and T-pose ──────────────────────────────────────────────────────────

Deno.test("SPEC G47: skeletonDisks — one disk per bone + skull/wrists/palms/balls, unit normals, plan radii, symmetric", () => {
  for (const race of RACES) {
    const plan = anatomyFor(specOf(race)), D = skeletonDisks(plan);
    assert(D.length === plan.bones.length + 1 + 4 + 2, `${race}: ${D.length} disks`);
    for (const d of D) {
      assert(d.at.every(Number.isFinite) && d.rx > 0 && d.rz > 0 && d.rx < 0.4 && d.rz < 0.4, `${race} ${d.bone}/${d.label}: ${JSON.stringify(d)}`);
      assert(Math.abs(Math.hypot(...d.normal) - 1) < 1e-9, `${race} ${d.bone}: normal not unit`);
    }
    const chest = D.find((d) => d.label === "chest")!;
    assert(chest.rx === plan.proportions.halfWidth.chest && chest.rz === plan.proportions.halfDepth.chest, `${race}: chest disk from the plan radii`);
    const L = D.find((d) => d.bone === "kneeL" && d.label === "knee")!, R = D.find((d) => d.bone === "kneeR" && d.label === "knee")!;
    assert(Math.abs(L.at[0] + R.at[0]) < 1e-9 && L.rx === R.rx, `${race}: knees mirror`);
  }
});

Deno.test("SPEC G48: tPose — arms straight and horizontal at shoulder height, lengths kept, trunk and legs untouched", () => {
  for (const race of RACES) {
    const plan = anatomyFor(specOf(race)), T = tPose(plan), B = tPoseBones(plan);
    const len = (a: Vec3, b: Vec3) => Math.hypot(a[0] - b[0], a[1] - b[1], a[2] - b[2]);
    for (const s of ["L", "R"]) {
      const up = plan.bones.find((b) => b.id === `shoulder${s}`)!, fore = plan.bones.find((b) => b.id === `elbow${s}`)!;
      const S = T[`shoulder${s}` as JointName], E = T[`elbow${s}` as JointName];
      assert(Math.abs(E[1] - S[1]) < 1e-9 && Math.abs(E[2] - S[2]) < 1e-9, `${race} ${s}: elbow not level with the shoulder`);
      assert(Math.abs(len(S, E) - len(up.head, up.tail)) < 1e-6, `${race} ${s}: upper arm length`);
      assert(Math.sign(E[0] - S[0]) === Math.sign(S[0]), `${race} ${s}: arm points outward`);
      const tb = B.find((b) => b.id === fore.id)!;
      assert(Math.abs(len(tb.head, tb.tail) - len(fore.head, fore.tail)) < 0.01, `${race} ${s}: forearm length ${len(tb.head, tb.tail)} vs ${len(fore.head, fore.tail)}`);
      assert(Math.abs(tb.tail[1] - S[1]) < 1e-9, `${race} ${s}: hand level`);
    }
    for (const b of plan.bones) if (!b.id.startsWith("shoulder") && !b.id.startsWith("elbow")) assert(JSON.stringify(T[b.id]) === JSON.stringify(b.head), `${race} ${b.id} moved`);
    const disks = tPoseDisks(plan);
    const palm = disks.find((d) => d.label === "palm" && d.bone === "elbowL")!;
    assert(Math.abs(palm.at[1] - T.shoulderL[1]) < 1e-9 && palm.normal[0] === Math.sign(T.shoulderL[0]), `${race}: T-pose palm disk on the arm line`);
  }
});

// ─── Balance disk ──────────────────────────────────────────────────────────────────────────────

Deno.test("SPEC G49: BalanceDisk maths — hull, signed margin, capsule centre of mass, lateral XCoM", () => {
  const sq: [number, number][] = [[0, 0], [1, 0], [1, 1], [0, 1], [0.5, 0.5]];
  const h = convexHull(sq);
  assert(h.length === 4, `hull ${JSON.stringify(h)}`);
  assert(Math.abs(polygonMargin([0.5, 0.5], h) - 0.5) < 1e-12 && Math.abs(polygonMargin([1.5, 0.5], h) + 0.5) < 1e-12, "margin sign");
  const caps = [{ wa: [0, 0, 0], wb: [0, 1, 0], radius: 0.1 }, { wa: [1, 0, 0], wb: [1, 1, 0], radius: 0.1 }];
  const com = capsuleCentreOfMass(caps);
  assert(Math.abs(com[0] - 0.5) < 1e-12 && Math.abs(com[1] - 0.5) < 1e-12, `com ${com}`);
  assert(balanceDisk(caps, [[0, -1], [1, -1], [1, 1], [0, 1]]).margin > 0.49, "disk inside");
  // A body moving toward its left stance foot's outer edge loses lateral margin.
  const still = lateralXcomMargin([0, 1, 0], [0, 0], [[0.1, 0], [0.2, 0]], 0, 0), moving = lateralXcomMargin([0, 1, 0], [0.5, 0], [[0.1, 0], [0.2, 0]], 0, 0);
  assert(Math.abs(still - 0.2) < 1e-12 && moving < still, `lateral XCoM ${still} ${moving}`);
});

Deno.test("SPEC G50: the balance disk holds — idle and guard keep the centre of mass inside both feet (4 races, real rigs)", () => {
  const lines: string[] = [];
  for (const body of ["human", "elfF", "dwarf", "orkF"]) {
    for (const id of ["idle", "guard"]) {
      const res = runClip(body, allClips("dagger").find((c) => c.id === id)!, new Map(), null, null);
      const b = res.balance.find((x) => x.stance === id)!;
      lines.push(`${body} ${id} ${b.marginMm.toFixed(0)} mm (double support ${(100 * (b.doubleShare ?? 0)).toFixed(0)} %)`);
      assert(b.marginMm > 20, `${body} ${id}: balance margin ${b.marginMm.toFixed(1)} mm`);
      assert((b.doubleShare ?? 0) > 0.9, `${body} ${id}: stance not in double support`);
    }
  }
  console.log(lines.join("\n"));
});

// ─── Audit fixes ───────────────────────────────────────────────────────────────────────────────

Deno.test("SPEC G51: the self guard counts a hand-and-a-half weapon as two-handed (its off hand holds the haft)", () => {
  const ls = weaponFromSeed("longsword", 7), sw = weaponFromSeed("shortsword", 7);
  const box = (side: "L" | "R", zone: "hand" | "foreArm") => ({ zone, side, bone: "elbowL", a: [0, 0, 0], b: [0, 0, 0], radius: 0.04, wa: [0, 0, 0], wb: [0, 0, 0] }) as unknown as Hitbox;
  assert(ls.hands >= 1.5 && ls.hands < 2, `longsword hands ${ls.hands}`);
  assert(gripExcluded(box("L", "hand"), ls) && gripExcluded(box("L", "foreArm"), ls), "longsword: the off hand is on the haft");
  assert(!gripExcluded(box("L", "hand"), sw) && gripExcluded(box("R", "hand"), sw), "shortsword: only the weapon hand");
});

Deno.test("SPEC G52: no render pops — off arm, fall start and get-up stay under the pop bound (human + ork, two-handed carry)", () => {
  assert(OFF_ARM_RATE === ARM_RELEASE_RATE, "the off arm's limiter and its release share one rate");
  assert(OFF_ARM_RATE / 60 < THRESHOLDS.popRad, "the limiter's per-frame step is under the pop bound");
  for (const body of ["human", "ork"]) {
    const cache = new Map();
    // (Skills / dashes keep residual weapon-shoulder pops where the torso forces the convergence down at once:
    // the body outranks continuity — KINEMATICS.md open issues.)
    for (const id of ["walk", "guard", "fall:back", "fall:side", "swing:greataxe"]) {
      const res = runClip(body, allClips("longsword").find((c) => c.id === id)!, cache, null, null);
      for (const r of res.runs) assert(Math.max(r.popBone, r.popJoint) < THRESHOLDS.popRad, `${body} ${id}/${r.tag}: pop ${r.popBone.toFixed(3)} rad (${r.popBoneName})`);
    }
  }
});

Deno.test("SPEC G53: a latched foot stays put through a fall's buckle while the body travels (≤ 60 mm; HEAD 104 mm)", () => {
  for (const body of ["human", "dwarfF"]) {
    for (const pose of ["back", "front"]) {
      const res = runClip(body, allClips("dagger").find((c) => c.id === `fall:${pose}`)!, new Map(), null, null);
      const fall = res.runs.find((r) => r.tag === "fall")!;
      assert(fall.slideMm <= 60, `${body} fall:${pose}: planted slide ${fall.slideMm.toFixed(1)} mm`);
    }
  }
});

Deno.test("SPEC G54: the two-handed carry keeps the blade out of the holder (walk / guard / idle, every race)", () => {
  for (const body of ["human", "elf", "dwarf", "ork"]) {
    const cache = new Map();
    for (const id of ["idle", "guard", "walk"]) {
      const res = runClip(body, allClips("longsword").find((c) => c.id === id)!, cache, null, null);
      for (const r of res.runs) assert(r.weaponMm <= THRESHOLDS.weaponMm, `${body} ${id}: blade ${r.weaponMm.toFixed(1)} mm into ${r.weaponBox}`);
    }
  }
});

// ─── The audit itself ──────────────────────────────────────────────────────────────────────────

Deno.test("SPEC G55: the audit drives every clip the game plays — every archetype's swing, every skill, falls and reactions", () => {
  const ids = new Set(allClips().map((c) => c.id));
  for (const a of ARCHETYPE_IDS) assert(ids.has(`swing:${a}`), `swing:${a}`);
  for (const s of ALL_SKILLS) assert([...ids].some((i) => i.endsWith(`:${s.id}`)), s.id);
  for (const k of ["idle", "guard", "block", "walk", "run", "strafe", "backpedal", "turn", "shove", "stagger", "stumble", "fall:back", "fall:front", "fall:side"]) assert(ids.has(k), k);
  assert(Object.keys(BODIES).length === 8 && new Set(Object.values(BODIES).map((b) => b.race)).size === 4, "4 races x 2 sexes");
});

const read = (p: string) => JSON.parse(Deno.readTextFileSync(p)) as AuditReport;

Deno.test("SPEC G56: the audit JSONs cover 8 bodies x every clip; after the fixes pops / blade-in-body / fall slides drop", () => {
  const before = read("artifacts/wave-gen/anim-audit-before.json"), after = read("artifacts/wave-gen/anim-audit-after.json");
  for (const rep of [before, after]) {
    assert(new Set(rep.runs.map((r) => r.body)).size === 8, "8 bodies");
    assert(rep.runs.length >= 8 * (allClips().length + 2 * 3), `${rep.runs.length} runs`);
  }
  // Classify with today's thresholds (docTables re-derives offences in place).
  docTables(before, after);
  const off = (rep: AuditReport, k?: string) => rep.runs.filter((r) => k ? r.offences.includes(k) : r.offences.length).length;
  console.log(`offending runs: before ${off(before)} -> after ${off(after)}; pops ${off(before, "pop")} -> ${off(after, "pop")}; weapon ${off(before, "weapon")} -> ${off(after, "weapon")}`);
  // The forearm->torso overlap of the two-handed carry is an OPEN issue (KINEMATICS.md), so "any" is not
  // pinned; the metrics this lane fixed are.
  assert(off(after, "pop") * 3 < off(before, "pop"), "pops cut by more than 3x");
  assert(off(after, "weapon") * 3 < off(before, "weapon"), "blade-in-body runs cut by more than 3x");
  const fallSlide = (rep: AuditReport) => Math.max(...rep.runs.filter((r) => r.kind === "fall" && r.tag === "fall").map((r) => r.slideMm));
  assert(fallSlide(after) < 0.7 * fallSlide(before), `fall buckle slide ${fallSlide(before).toFixed(0)} -> ${fallSlide(after).toFixed(0)} mm`);
});

Deno.test("SPEC G57: docs/wave-gen/KINEMATICS.md carries the tables generated from the audit JSONs", () => {
  const doc = Deno.readTextFileSync("docs/wave-gen/KINEMATICS.md");
  const tables = docTables(read("artifacts/wave-gen/anim-audit-before.json"), read("artifacts/wave-gen/anim-audit-after.json"));
  const konly = docTables(read("artifacts/wave-gen/anim-audit-before.json"), read("artifacts/wave-gen/anim-audit-after-k-only.json"));
  const agi = agilityTable(JSON.parse(Deno.readTextFileSync("artifacts/wave-gen/anim-agility.json")));
  for (const [name, t] of [["tree", tables], ["k-only", konly], ["agility", agi]] as const) {
    assert(doc.includes(t), `KINEMATICS.md ${name} tables differ from the JSONs (regenerate: deno run -A tools/audit-animations.ts --write-doc)`);
  }
});

Deno.test("SPEC G58: the balance margins in the audit are all positive for standing stances (8 bodies)", () => {
  const after = read("artifacts/wave-gen/anim-audit-after.json");
  for (const b of after.balance.filter((x) => x.stance === "idle" || x.stance === "guard")) assert(b.marginMm > 20, `${b.body} ${b.stance}: ${b.marginMm.toFixed(0)} mm`);
  for (const b of after.balance.filter((x) => x.stance === "walk-midstance")) assert((b.xcomMm ?? -1) > 0, `${b.body} walk: lateral XCoM margin ${b.xcomMm}`);
});

Deno.test("SPEC G59: the agility reach meter — agility 1000 widens the audited reach envelope, the reference does not move it", () => {
  const rep = read("artifacts/wave-gen/anim-agility.json") as unknown as { travel: Record<string, number>; reach: Record<string, Record<string, Record<string, [number, number]>>> };
  assert(rep.travel["1000"] > rep.travel["500"] && rep.travel["500"] > rep.travel["0"], `travel ${JSON.stringify(rep.travel)}`);
  const span = (r: Record<string, [number, number]>) => Object.values(r).reduce((s, [a, b]) => s + b - a, 0);
  for (const body of Object.keys(rep.reach["500"])) {
    assert(span(rep.reach["1000"][body]) > span(rep.reach["500"][body]), `${body}: agile reach not wider`);
  }
});
